#include <stdio.h>
#include <stdlib.h>

#define MAX_N 300000

int parent[MAX_N + 1];
int size[MAX_N + 1];

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void unite(int a, int b) {
    int ra = find(a);
    int rb = find(b);
    if (ra == rb) return;
    if (size[ra] < size[rb]) {
        int tmp = ra;
        ra = rb;
        rb = tmp;
    }
    parent[rb] = ra;
    size[ra] += size[rb];
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    for (int i = 1; i <= N; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        unite(u, v);
    }

    int comp_count = 0;
    for (int i = 1; i <= N; i++) {
        if (find(i) == i) comp_count++;
    }

    long long result = (long long)comp_count * comp_count;
    printf("%lld\n", result);

    return 0;
}

