#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *deg = (int *)calloc(N, sizeof(int));
    int *U = (int *)malloc(sizeof(int) * M);
    int *V = (int *)malloc(sizeof(int) * M);

    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v;
        U[i] = u;
        V[i] = v;
        deg[u]++;
        deg[v]++;
    }

    int *offset = (int *)malloc(sizeof(int) * (N + 1));
    offset[0] = 0;
    for (int i = 0; i < N; i++) offset[i + 1] = offset[i] + deg[i];

    int *adj = (int *)malloc(sizeof(int) * (2 * M));
    int *cur = (int *)calloc(N, sizeof(int));
    for (int i = 0; i < M; i++) {
        int u = U[i], v = V[i];
        adj[offset[u] + cur[u]++] = v;
        adj[offset[v] + cur[v]++] = u;
    }

    int *color = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) color[i] = -1;

    int *queue = (int *)malloc(sizeof(int) * N);
    ll *cnt = (ll *)calloc(2, sizeof(ll)); /* sizes of bipartition classes over all connected components */
    ll isolated = 0;

    int is_bip = 1;

    for (int s = 0; s < N; s++) {
        if (color[s] != -1) continue;

        if (deg[s] == 0) {
            color[s] = 0;
            isolated++;
            continue;
        }

        int head = 0, tail = 0;
        queue[tail++] = s;
        color[s] = 0;
        ll local[2] = {1, 0};

        while (head < tail) {
            int v = queue[head++];
            for (int ei = offset[v]; ei < offset[v + 1]; ei++) {
                int to = adj[ei];
                if (color[to] == -1) {
                    color[to] = color[v] ^ 1;
                    local[color[to]]++;
                    queue[tail++] = to;
                } else if (color[to] == color[v]) {
                    is_bip = 0;
                }
            }
        }

        cnt[0] += local[0];
        cnt[1] += local[1];
    }

    ll ans;
    if (!is_bip) {
        ans = 1;
    } else {
        /* 
           If G is bipartite, then G × G has:
           - 4 components if G has at least one non-isolated connected component
             split by parity pairs (0,0), (0,1), (1,0), (1,1),
             but some may be empty globally depending on total side sizes.
           - isolated vertices (u,v) whenever u or v is isolated in G.

           Counting directly:
           Non-isolated/non-isolated pairs split into:
             cnt[0]^2, cnt[0]*cnt[1], cnt[1]*cnt[0], cnt[1]^2
           Each non-empty class is one connected component.
           Any pair with at least one isolated endpoint is itself isolated in G×G.
        */

        ans = 0;
        if (cnt[0] > 0) ans++;
        if (cnt[1] > 0) ans++;
        if (cnt[0] > 0 && cnt[1] > 0) ans += 2;

        ll noniso = cnt[0] + cnt[1];
        ll iso_pairs = (ll)N * (ll)N - noniso * noniso;
        ans += iso_pairs;
    }

    printf("%lld\n", ans);

    free(deg);
    free(U);
    free(V);
    free(offset);
    free(adj);
    free(cur);
    free(color);
    free(queue);
    free(cnt);

    return 0;
}

