    cin >> N >> M;

    vector<vector<int>> g(N);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    vector<int> comp(N, -1);
    vector<int> bip(N, -1);
    vector<int> sz;
    vector<bool> is_bip;

    int cid = 0;
    for (int s = 0; s < N; ++s) {
        if (comp[s] != -1) continue;

        queue<int> q;
        q.push(s);
        comp[s] = cid;
        bip[s] = 0;

        int cnt = 0;
        bool ok = true;

        while (!q.empty()) {
            int v = q.front();
            q.pop();
            ++cnt;

            for (int to : g[v]) {
                if (comp[to] == -1) {
                    comp[to] = cid;
                    bip[to] = bip[v] ^ 1;
                    q.push(to);
                } else {
                    if (bip[to] == bip[v]) ok = false;
                }
            }
        }

        sz.push_back(cnt);
        is_bip.push_back(ok);
        ++cid;
    }

    long long ans = 0;
    int C = cid;

    for (int i = 0; i < C; ++i) {
        for (int j = 0; j < C; ++j) {
            if (i == j) {
                if (is_bip[i]) ans += 2;
                else ans += 1;
            } else {
                ans += 1;
            }
        }
    }

    cout << ans << '\n';
    return 0;
