import java.io.*;
import java.util.*;

/*
Key idea:
Let G be the original undirected graph.
Construct H on ordered pairs (a,b). There is an edge between (a,b) and (a',b')
iff aa' is an edge in G and bb' is an edge in G.

We need the number of connected components of H.

For each connected component C of G:
- If C is bipartite with color classes sizes x,y, then in H restricted to C×C,
  there are exactly 2 connected components:
    S0 = {(u,v) | color(u)=color(v)}
    S1 = {(u,v) | color(u)!=color(v)}
  unless |C|=1, where H has just one isolated vertex, so 1 component.
- If C is non-bipartite, then C×C is connected in H, so 1 component.

Also, there are no edges in H between pairs coming from different connected components of G
in either coordinate, so total answer is the sum over connected components of G of:
- 1 if size=1
- 2 if bipartite and size>=2
- 1 if non-bipartite

Thus answer = (#non-bipartite components) + 2*(#bipartite components of size>=2) + (#isolated vertices)

Equivalent implementation: DFS/BFS each component, test bipartiteness and size.
*/

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();

        List<Integer>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
        }

        int[] color = new int[N];
        Arrays.fill(color, -1);
        long ans = 0;

        ArrayDeque<Integer> q = new ArrayDeque<>();

        for (int s = 0; s < N; s++) {
            if (color[s] != -1) continue;

            color[s] = 0;
            q.add(s);
            int size = 0;
            boolean bipartite = true;

            while (!q.isEmpty()) {
                int v = q.poll();
                size++;
                for (int to : g[v]) {
                    if (color[to] == -1) {
                        color[to] = color[v] ^ 1;
                        q.add(to);
                    } else if (color[to] == color[v]) {
                        bipartite = false;
                    }
                }
            }

            if (size == 1) ans += 1;
            else if (bipartite) ans += 2;
            else ans += 1;
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
